fn reader_guard_inductive(pre: Self, post: Self, node_id: NodeId) {
    assert(pre.all_reader_state_valid());
    assert(pre.ranges_no_overlap());
    assert(post.combiner.contains_key(node_id));
    assert(post.combiner[node_id].is_Reading());
    assert forall |n| #[trigger] post.combiner.contains_key(n)
        && post.combiner[n].is_Reading() implies
        post.reader_state_valid(n, post.combiner[n].get_Reading_0()) by {
        if n == node_id {
            assert(post.combiner[n] == CombinerState::Reading(
                ReaderState::Guard { start: _, end: _, cur: _, val: _ }));
            assert(post.reader_state_valid(n, post.combiner[n].get_Reading_0()));
        } else {
            assert(pre.combiner.contains_key(n));
            assert(pre.combiner[n] == post.combiner[n]);
            assert(pre.all_reader_state_valid());
            assert(pre.reader_state_valid(n, pre.combiner[n].get_Reading_0()));
        }
    };

    assert forall |i, j| post.combiner.contains_key(i) && post.combiner.contains_key(j)
        && i != j ==> post.combiner[i].no_overlap_with(post.combiner[j]) by {
        if i == node_id {
            assert(post.combiner[i].no_overlap_with(post.combiner[j]));
        } else if j == node_id {
            if post.combiner[i].is_Appending() {
                let CombinerState::Appending { cur_idx, tail } = post.combiner[i];
                let CombinerState::Reading(ReaderState::Guard { cur, .. }) = post.combiner[j];
                assert(cur_idx > cur || tail <= cur);
            } else {
                assert(post.combiner[i].no_overlap_with(post.combiner[j]));
            }
        } else {
            assert(pre.combiner[i].no_overlap_with(pre.combiner[j]));
            assert(post.combiner[i] == pre.combiner[i]);
            assert(post.combiner[j] == pre.combiner[j]);
        }
    };
}

